const cv = $("fx"), cx = cv.getContext("2d");
let bits = [], fxRun = false, fxLast = 0;
function sizeFx(){ const d = Math.min(2, devicePixelRatio || 1); cv.width = innerWidth * d; cv.height = innerHeight * d; cx.setTransform(d, 0, 0, d, 0, 0); }
