function dust(n, x, y, spread){
  const col = Math.min(innerWidth, document.querySelector(".inv").getBoundingClientRect().width), x0 = (innerWidth - col) / 2;
  for (let i = 0; i < n; i++) {
    const at = x != null;
    bits.push({ x: at ? x + (Math.random() - .5) * (spread || 30) : x0 + Math.random() * col, y: at ? y + (Math.random() - .5) * (spread || 30) : -12 - Math.random() * innerHeight * .4,
      vx: (Math.random() - .5) * (at ? 60 : 18), vy: at ? -20 + Math.random() * 60 : 30 + Math.random() * 42, s: 1.2 + Math.random() * 2.2, ph: Math.random() * 6.3, life: at ? .9 + Math.random() * .9 : 5 + Math.random() * 4, c: ["#FFE7B0", "#E9C77E", "#FFF6DE", "#D4AE63"][i % 4] });
  }
  if (bits.length > 220) bits.splice(0, bits.length - 220);
  if (!fxRun) { fxRun = true; fxLast = performance.now(); requestAnimationFrame(step); }
}
function step(t){
  const dt = Math.min(.033, (t - fxLast) / 1000); fxLast = t;
  cx.clearRect(0, 0, innerWidth, innerHeight);
  bits = bits.filter(b => b.y < innerHeight + 20 && (b.life -= dt) > 0);
  for (const b of bits) {
    b.ph += dt; b.x += (b.vx + Math.sin(b.ph * 1.3) * 12) * dt; b.y += b.vy * dt; b.vx *= .985;
    const tw = (.45 + .55 * Math.abs(Math.sin(b.ph * 2.6))) * Math.min(1, b.life * 2);
    const g = cx.createRadialGradient(b.x, b.y, 0, b.x, b.y, b.s * 3.2); g.addColorStop(0, b.c); g.addColorStop(.35, b.c); g.addColorStop(1, "rgba(255,220,150,0)");
    cx.globalAlpha = tw; cx.fillStyle = g; cx.beginPath(); cx.arc(b.x, b.y, b.s * 3.2, 0, 6.283); cx.fill();
  }
  cx.globalAlpha = 1;
  if (bits.length) requestAnimationFrame(step); else { fxRun = false; cx.clearRect(0, 0, innerWidth, innerHeight); }
}

